public static HSTFCardRecNewPlatformInfo createFrom(RecordVideoInfo recordVideoInfo) {
    if (recordVideoInfo == null) {
        return null;
    }
    HSTFCardRecNewPlatformInfo hSTFCardRecNewPlatformInfo = new HSTFCardRecNewPlatformInfo();
    hSTFCardRecNewPlatformInfo.nFileSource = 6;
    RecSegment recSegment = recordVideoInfo.getRecSegment();
    hSTFCardRecNewPlatformInfo.nFileType = recSegment.getnType();
    hSTFCardRecNewPlatformInfo.nSegmentID = recSegment.getnSegmentID();
    hSTFCardRecNewPlatformInfo.uYear = recSegment.getNvtStartTime().getuYear();
    hSTFCardRecNewPlatformInfo.uMonth = recSegment.getNvtStartTime().getuMonth();
    hSTFCardRecNewPlatformInfo.uDay = recSegment.getNvtStartTime().getuDay();
    hSTFCardRecNewPlatformInfo.uStartHour = recSegment.getNvtStartTime().getuHour();
    hSTFCardRecNewPlatformInfo.uStartMin = recSegment.getNvtStartTime().getuMin();
    hSTFCardRecNewPlatformInfo.uStartSec = recSegment.getNvtStartTime().getuSec();
    hSTFCardRecNewPlatformInfo.lStartTime = recSegment.getNvtStartTime().getlTime();
    hSTFCardRecNewPlatformInfo.lEndTime = recSegment.getNvtEndTime().getlTime();
    return hSTFCardRecNewPlatformInfo;
}
